# Generated by manage.py generate_test_cases.
from uuid import uuid4
from unittest.mock import patch

from django.http import HttpResponse
from django.utils import timezone

from bloomerp.communication.builtins.instant_messaging.controller import IMController
from bloomerp.models.communication.instant_messaging import (
    IMConversation,
    IMConversationParticipant,
    IMMessage,
)
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.models.communication.voip.fixtures import VoIPFixtures


class TestSendMessageComponent(VoIPFixtures, BloomerpComponentTestCase):
    """Exercise persistence, retries, editor sanitization and membership at send time."""

    view_name = "components_im_send_message"

    def prepare_sms(self, scenario: RequestScenario) -> None:
        """Submit editor HTML to an assigned phone chat with carrier delivery mocked."""
        self.prepare_voip()
        self.sms_adapter = self.enterContext(
            patch("bloomerp.communication.builtins.voip.controller.adapter_for")
        ).return_value
        self.sms_adapter.send_sms.return_value = "SM" + "6" * 32
        scenario.view_kwargs = {"conversation_id": self.chat.pk}
        scenario.data = {
            "body_html": "<p>Hello <strong>team</strong><script>alert(1)</script></p>",
            "client_id": "send-test",
        }
        self.sms_body = "Hello team"

    def prepare_sms_at_limit(self, scenario: RequestScenario) -> None:
        """Keep plain text at the carrier limit while editor markup exceeds it."""
        self.prepare_sms(scenario)
        self.sms_body = "x" * 1600
        scenario.data["body_html"] = f"<p><strong>{self.sms_body}</strong></p>"

    def prepare_sms_over_limit(self, scenario: RequestScenario) -> None:
        """Submit plain text beyond the carrier limit before any network dispatch."""
        self.prepare_sms_at_limit(scenario)
        scenario.data["body_html"] = f"<p>{self.sms_body}x</p>"

    def validate_sms(self, response: HttpResponse) -> bool:
        """Verify persistence and carrier delivery use the same plain-text body."""
        message = IMMessage.objects.get(conversation=self.chat)
        self.sms_adapter.send_sms.assert_called_once()
        return (
            message.body == self.sms_body
            and message.status == "accepted"
            and self.sms_adapter.send_sms.call_args.args[:3]
            == (self.number.number, self.chat.phone_address, self.sms_body)
        )

    def validate_sms_rejected(self, response: HttpResponse) -> bool:
        """Reject excessive text without saving a message or contacting the carrier."""
        self.sms_adapter.send_sms.assert_not_called()
        return not self.chat.messages.exists()

    def prepare_message(self, scenario: RequestScenario) -> None:
        """Prepare one native chat and a formatted message payload."""
        self.chat = IMConversation.objects.create(kind="group")
        self.member = IMConversationParticipant.objects.create(
            conversation=self.chat, user=self.normal_user
        )
        scenario.view_kwargs = {"conversation_id": self.chat.pk}
        scenario.data = {
            "body_html": "<p>Hello <strong>team</strong><script>alert(1)</script></p>",
            "client_id": "send-test",
        }

    def prepare_retry(self, scenario: RequestScenario) -> None:
        """Simulate retrying after the first response was lost."""
        self.prepare_message(scenario)
        IMController(self.normal_user).send_message(
            self.chat.pk, scenario.data["body_html"], "send-test"
        )

    def prepare_empty(self, scenario: RequestScenario) -> None:
        """Submit an editor with no meaningful text."""
        self.prepare_message(scenario)
        scenario.data["body_html"] = "<p><br></p>"

    def prepare_revoked(self, scenario: RequestScenario) -> None:
        """Remove membership before the request reaches the controller."""
        self.prepare_message(scenario)
        self.member.left_at = timezone.now()
        self.member.save()

    def prepare_reply(self, scenario: RequestScenario) -> None:
        """Send a quoted reply inside an existing thread."""
        self.prepare_message(scenario)
        self.root = IMMessage.objects.create(
            conversation=self.chat, sender=self.member, sequence=1, body="Root"
        )
        scenario.data.update(reply_to=str(self.root.pk), thread_root=str(self.root.pk))

    def prepare_tag(self, scenario: RequestScenario) -> None:
        """Submit a real reference with an untrusted browser-provided label."""
        self.prepare_message(scenario)
        scenario.data["body_html"] = (
            f'<p><span data-reference-kind="user" data-target-id="{self.normal_user.pk}" data-occurrence-id="{uuid4()}">Forged label</span></p>'
        )

    def prepare_tag_for_admin(self, scenario: RequestScenario) -> None:
        """Use an authorized tag reader who is also a conversation member."""
        self.prepare_tag(scenario)
        IMConversationParticipant.objects.create(
            conversation=self.chat, user=self.admin_user
        )

    def prepare_bad_tag(self, scenario: RequestScenario) -> None:
        """Reject a nonexistent target even with structurally valid reference HTML."""
        self.prepare_message(scenario)
        scenario.data["body_html"] = (
            f'<p><span data-reference-kind="user" data-target-id="{uuid4()}" data-occurrence-id="{uuid4()}">Forged label</span></p>'
        )

    def prepare_archived(self, scenario: RequestScenario) -> None:
        """Prevent writes to an archived conversation."""
        self.prepare_message(scenario)
        self.chat.status = "archived"
        self.chat.save()

    def prepare_foreign_quote(self, scenario: RequestScenario) -> None:
        """Reject a quoted message outside the selected conversation."""
        self.prepare_message(scenario)
        other = IMConversation.objects.create(kind="group")
        member = IMConversationParticipant.objects.create(
            conversation=other, user=self.normal_user
        )
        message = IMMessage.objects.create(
            conversation=other, sender=member, sequence=1, body="Foreign"
        )
        scenario.data["reply_to"] = str(message.pk)

    def validate_tag(self, response: HttpResponse) -> bool:
        """Retain stable reference metadata with the authorized canonical label."""
        message = IMMessage.objects.get(conversation=self.chat)
        return (
            message.body == str(self.normal_user)
            and "Forged label" not in message.body_html
            and "data-target-id" in message.body_html
        )

    def validate_reply(self, response: HttpResponse) -> bool:
        """Verify both forms of reply survive persistence."""
        message = IMMessage.objects.get(client_id="send-test")
        return (
            message.reply_to_id == self.root.pk
            and message.thread_root_id == self.root.pk
            and message.sequence == 2
        )

    def validate_message(self, response: HttpResponse) -> bool:
        """Check sanitized HTML, searchable text and exactly-once local persistence."""
        message = IMMessage.objects.get(conversation=self.chat)
        return (
            message.body == "Hello team"
            and message.body_html == "<p>Hello <strong>team</strong></p>"
            and message.status == "sent"
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover successful sending and rejected requests using generated scenarios."""
        return [
            RequestScenario(
                name="SMS sends plain text from editor markup",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_sms,
                expected=ExpectedResult(response_validators=[self.validate_sms]),
            ),
            RequestScenario(
                name="SMS length limit counts plain text",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_sms_at_limit,
                expected=ExpectedResult(response_validators=[self.validate_sms]),
            ),
            RequestScenario(
                name="SMS rejects plain text over the carrier limit",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_sms_over_limit,
                expected=ExpectedResult(
                    status_code=400,
                    response_validators=[self.validate_sms_rejected],
                ),
            ),
            RequestScenario(
                name="Canonical user tag",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_tag_for_admin,
                expected=ExpectedResult(response_validators=[self.validate_tag]),
            ),
            RequestScenario(
                name="Forged reference rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_bad_tag,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Archived conversation rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_archived,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Foreign quote rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_foreign_quote,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Send rich message",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_message,
                expected=ExpectedResult(response_validators=[self.validate_message]),
            ),
            RequestScenario(
                name="Retry does not duplicate",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_retry,
                expected=ExpectedResult(response_validators=[self.validate_message]),
            ),
            RequestScenario(
                name="Quote inside thread",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_reply,
                expected=ExpectedResult(response_validators=[self.validate_reply]),
            ),
            RequestScenario(
                name="Empty editor rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_empty,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Former member denied",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_revoked,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Other user denied",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_message,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Anonymous denied",
                method="POST",
                prepare=self.prepare_message,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="GET cannot send",
                user=self.normal_user,
                prepare=self.prepare_message,
                expected=ExpectedResult(status_code=405),
            ),
        ]
